package com.howierux.mortalexpansion.gametest;
import com.howierux.mortalexpansion.catalog.*;import com.howierux.mortalexpansion.travel.*;import com.howierux.mortalexpansion.haunt.*;import net.fabricmc.fabric.api.gametest.v1.FabricGameTest;import net.minecraft.gametest.framework.*;import net.minecraft.core.*;import net.minecraft.world.item.*;import net.minecraft.world.level.block.*;import java.util.*;
public final class ParityGameTests implements FabricGameTest {
 static net.minecraft.server.level.ServerPlayer player(GameTestHelper h){var p=RemainingSlicesGameTests.player(h);for(int i=0;i<65;i++)p.tick();return p;}
 static void remove(GameTestHelper h,net.minecraft.server.level.ServerPlayer p){var live=p.getServer().getPlayerList().getPlayer(p.getUUID());if(live!=null)RemainingSlicesGameTests.remove(h,live);}
 static BlockPos grave(GameTestHelper h,net.minecraft.server.level.ServerPlayer p,boolean natural){var pos=h.absolutePos(new BlockPos(4,3,3));for(int x=-2;x<=2;x++)for(int z=-2;z<=2;z++)h.getLevel().setBlockAndUpdate(pos.offset(x,-1,z),Blocks.STONE.defaultBlockState());h.getLevel().setBlockAndUpdate(pos,CatalogBlocks.GRAVE.defaultBlockState());var g=(GraveEntity)h.getLevel().getBlockEntity(pos);g.placed(p);g.name(p,p.getGameProfile().getName());if(natural)h.getLevel().setBlockAndUpdate(pos,g.getBlockState().setValue(CatalogBlocks.GRAVE_NATURAL,true));return pos;}
 static void die(net.minecraft.server.level.ServerPlayer p){p.invulnerableTime=0;p.hurt(p.damageSources().fellOutOfWorld(),1000);}
 @GameTest(template=EMPTY_STRUCTURE,batch="parity") public void nonnatural_grave_is_consumed_on_normal_respawn(GameTestHelper h){var original=player(h);try{var pos=grave(h,original,false);PlayerHauntManager.setValue(original,20);die(original);var p=h.getLevel().getServer().getPlayerList().respawn(original,false,net.minecraft.world.entity.Entity.RemovalReason.KILLED);h.assertTrue(h.getLevel().getBlockState(pos).isAir()&&JourneyRuntime.graveTarget(p)==null&&PlayerHauntManager.getValue(p)==21,"One-use grave respawn consumes grave and adds one personal Haunt");h.assertTrue(p.position().distanceToSqr(pos.getCenter())<16,"Respawn arrives at grave before consuming it");h.succeed();}finally{remove(h,original);}}
 @GameTest(template=EMPTY_STRUCTURE,batch="parity") public void naturalized_grave_survives_normal_respawn_without_haunt_cost(GameTestHelper h){var original=player(h);try{var pos=grave(h,original,true);PlayerHauntManager.setValue(original,20);die(original);var p=h.getLevel().getServer().getPlayerList().respawn(original,false,net.minecraft.world.entity.Entity.RemovalReason.KILLED);h.assertTrue(h.getLevel().getBlockState(pos).is(CatalogBlocks.GRAVE)&&JourneyRuntime.graveTarget(p)!=null&&PlayerHauntManager.getValue(p)==20,"Naturalized grave and binding persist with no single-use respawn cost");h.succeed();}finally{remove(h,original);}}
 @GameTest(template=EMPTY_STRUCTURE,batch="parity") public void journey_preserves_manual_and_naturalized_graves_without_respawn_cost(GameTestHelper h){for(boolean natural:new boolean[]{false,true}){var original=player(h);try{var pos=grave(h,original,natural);PlayerHauntManager.setValue(original,20);die(original);h.assertTrue(JourneyRuntime.choose(original),"Dead bound player can select Journey");var p=original.getServer().getPlayerList().getPlayer(original.getUUID());h.assertTrue(JourneyRuntime.active(p)&&h.getLevel().getBlockState(pos).is(CatalogBlocks.GRAVE)&&JourneyRuntime.graveTarget(p)!=null&&PlayerHauntManager.getValue(p)==20,"Journey preserves the owned grave, binding and personal Haunt; naturalized="+natural);h.assertTrue(p.serverLevel().getEntity(java.util.UUID.fromString(JourneyRuntime.body(p)))!=null,"Preserved grave keeps corpse recovery available");}finally{remove(h,original);h.getLevel().removeBlock(h.absolutePos(new BlockPos(4,3,3)),false);}}h.succeed();}
 @GameTest(template=EMPTY_STRUCTURE,batch="parity") public void grave_placement_uses_all_thirds_and_facings(GameTestHelper h){var p=player(h);try{var pos=h.absolutePos(new BlockPos(3,3,3));h.getLevel().setBlockAndUpdate(pos.below(),Blocks.STONE.defaultBlockState());for(var facing:Direction.Plane.HORIZONTAL)for(int depth=0;depth<3;depth++){p.setYRot(facing.getOpposite().toYRot());double axis=(depth+.5)/3;var click=new net.minecraft.world.phys.Vec3(pos.getX()+(facing.getAxis()==Direction.Axis.X?axis:.5),pos.getY(),pos.getZ()+(facing.getAxis()==Direction.Axis.Z?axis:.5));var context=new net.minecraft.world.item.context.BlockPlaceContext(p,net.minecraft.world.InteractionHand.MAIN_HAND,new ItemStack(CatalogItems.GRAVE),new net.minecraft.world.phys.BlockHitResult(click,Direction.UP,pos.below(),false));var state=CatalogBlocks.GRAVE.getStateForPlacement(context);h.assertTrue(state.getValue(CatalogBlocks.GRAVE_DEPTH)==depth&&state.getValue(net.minecraft.world.level.block.state.properties.BlockStateProperties.HORIZONTAL_FACING)==facing,"Clicked third determines depth for every facing");}h.succeed();}finally{remove(h,p);}}
 @GameTest(template=EMPTY_STRUCTURE,batch="parity") public void reference_loot_rules_cover_ghasts_frames_and_double_slabs(GameTestHelper h){var pos=h.absolutePos(new BlockPos(3,3,3));var ghast=net.minecraft.world.entity.EntityType.GHAST.create(h.getLevel());ghast.setPos(pos.getCenter());h.getLevel().addFreshEntity(ghast);ghast.hurt(ghast.damageSources().fellOutOfWorld(),1000);h.assertTrue(h.getLevel().getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,new net.minecraft.world.phys.AABB(pos).inflate(3)).stream().filter(e->e.getItem().is(CatalogItems.RAW_ECTOPLASM)).mapToInt(e->e.getItem().getCount()).sum()==1,"Vanilla Ghast adds exactly one raw ectoplasm");h.assertTrue(Block.getDrops(CatalogBlocks.MORTAL_GOLEM_BASE.defaultBlockState(),h.getLevel(),pos,null).stream().anyMatch(s->s.is(Items.BONE_BLOCK)),"Breaking a fleshed frame returns its bone block");var slab=CatalogBlocks.SPIRITWOOD_SLAB.defaultBlockState().setValue(SlabBlock.TYPE,net.minecraft.world.level.block.state.properties.SlabType.DOUBLE);h.assertTrue(Block.getDrops(slab,h.getLevel(),pos,null).stream().filter(s->s.is(CatalogItems.SPIRITWOOD_SLAB)).mapToInt(ItemStack::getCount).sum()==1,"Preserve NeoForge's current one-item double-slab loot balance");h.succeed();}
 @GameTest(template=EMPTY_STRUCTURE,batch="parity") public void loaded_existing_wells_rebuild_discovery_index(GameTestHelper h){var pos=h.absolutePos(new BlockPos(3,3,3));h.getLevel().setBlockAndUpdate(pos,CatalogBlocks.SPIRITWELL.defaultBlockState());var index=com.howierux.mortalexpansion.spiritwell.SpiritwellIndex.get(h.getLevel());index.remove(pos);net.fabricmc.fabric.api.event.lifecycle.v1.ServerChunkEvents.CHUNK_LOAD.invoker().onChunkLoad(h.getLevel(),h.getLevel().getChunkAt(pos));h.assertTrue(index.knownPositions().contains(pos),"Loading an existing/generated well reindexes its block entity");h.succeed();}
 @GameTest(template=EMPTY_STRUCTURE,batch="parity") public void canonical_effect_command_has_reference_safety_semantics(GameTestHelper h){var p=player(h);try{var source=p.createCommandSourceStack().withPermission(4);var commands=p.getServer().getCommands().getDispatcher();int result=commands.execute("mortalexpansion haunt effect @s helpful_visitation",source);h.assertTrue(result==1&&p.getInventory().countItem(CatalogItems.SPIRIT_BOON)==1,"NeoForge canonical effect command works on Fabric");h.assertTrue(com.howierux.mortalexpansion.haunt.effects.HauntEventController.ready(p,false),"Operator command does not change natural cooldowns");long pending=com.howierux.mortalexpansion.haunt.effects.HauntEventData.get(h.getLevel()).pendingGhosts();commands.execute("mortalexpansion haunt effect @s ghost",source);h.assertTrue(com.howierux.mortalexpansion.haunt.effects.HauntEventData.get(h.getLevel()).pendingGhosts()==pending,"Targeted Ghost command never queues delivery to a different player");h.succeed();}catch(com.mojang.brigadier.exceptions.CommandSyntaxException e){throw new RuntimeException(e);}finally{remove(h,p);}}
 @GameTest(template=EMPTY_STRUCTURE,batch="parity") public void shared_diamond_tags_preserve_bloodstone_gear_patterns(GameTestHelper h){var b=new ItemStack(CatalogItems.BLOODSTONE);h.assertTrue(b.is(net.minecraft.tags.TagKey.create(net.minecraft.core.registries.Registries.ITEM,net.minecraft.resources.ResourceLocation.parse("c:gems/diamond"))),"Bloodstone belongs to common diamond gems");var empty=ItemStack.EMPTY;var input=net.minecraft.world.item.crafting.CraftingInput.of(3,3,List.of(empty,new ItemStack(Items.BOOK),empty,b,new ItemStack(Items.OBSIDIAN),b,new ItemStack(Items.OBSIDIAN),new ItemStack(Items.OBSIDIAN),new ItemStack(Items.OBSIDIAN)));var recipe=h.getLevel().getRecipeManager().getRecipeFor(net.minecraft.world.item.crafting.RecipeType.CRAFTING,input,h.getLevel()).orElseThrow();h.assertTrue(recipe.value().assemble(input,h.getLevel().registryAccess()).is(Items.ENCHANTING_TABLE),"Vanilla enchanting table accepts Bloodstone");var pick=net.minecraft.world.item.crafting.CraftingInput.of(3,3,List.of(b,b,b,empty,new ItemStack(Items.STICK),empty,empty,new ItemStack(Items.STICK),empty));var matches=h.getLevel().getRecipeManager().getAllRecipesFor(net.minecraft.world.item.crafting.RecipeType.CRAFTING).stream().filter(r->r.value().matches(pick,h.getLevel())).toList();h.assertTrue(matches.size()==1&&matches.getFirst().value().assemble(pick,h.getLevel().registryAccess()).is(CatalogItems.BLOODSTONE_PICKAXE),"All-Bloodstone pattern cannot overlap vanilla diamond gear");for(var holder:h.getLevel().getRecipeManager().getAllRecipesFor(net.minecraft.world.item.crafting.RecipeType.CRAFTING)){var output=holder.value().getResultItem(h.getLevel().registryAccess());boolean gear=output.getItem() instanceof net.minecraft.world.item.TieredItem||output.getItem() instanceof ArmorItem;for(var ing:holder.value().getIngredients())if(!gear&&ing.test(new ItemStack(Items.DIAMOND)))h.assertTrue(ing.test(b),"Non-gear diamond recipe accepts Bloodstone: "+holder.id());}h.succeed();}
 @GameTest(template=EMPTY_STRUCTURE,batch="parity") public void spawn_and_enchantment_tag_contracts_match_reference(GameTestHelper h){h.assertTrue(!com.howierux.mortalexpansion.combat.CombatSpawns.bypassLight(com.howierux.mortalexpansion.entity.CombatEntities.GHOST,true,6)&&com.howierux.mortalexpansion.combat.CombatSpawns.bypassLight(com.howierux.mortalexpansion.entity.CombatEntities.DEMON,true,5),"Only above-Demonic Demons bypass daylight light rules");var biome=h.getLevel().registryAccess().registryOrThrow(net.minecraft.core.registries.Registries.BIOME).get(net.minecraft.world.level.biome.Biomes.PLAINS);var spawns=biome.getMobSettings().getMobs(net.minecraft.world.entity.MobCategory.MONSTER).unwrap();h.assertTrue(spawns.stream().anyMatch(s->s.type==net.minecraft.world.entity.EntityType.GHAST)&&spawns.stream().anyMatch(s->s.type==net.minecraft.world.entity.EntityType.WITHER_SKELETON),"Overworld population includes gated Ghasts and Wither Skeletons");h.assertTrue(new ItemStack(CatalogItems.GHOST_GARB_HELMET).is(net.minecraft.tags.TagKey.create(net.minecraft.core.registries.Registries.ITEM,net.minecraft.resources.ResourceLocation.parse("minecraft:enchantable/head_armor"))),"Garb supports native slot enchantments");h.assertTrue(h.getLevel().damageSources().source(com.howierux.mortalexpansion.effect.ModDamageTypes.SANCTIFICATION).is(net.minecraft.tags.DamageTypeTags.BYPASSES_ARMOR),"Sanctification retains armor bypass tag");h.succeed();}
}
